#   adapter_report_audit.py
#
# Layer:
#   CORE / CONTRACTS / AUDIT
#
# ROLE:
#
#   Immutable adapter audit artifact.
#
# PURPOSE:
#
#   Stores deterministic adapter conversion evidence
#   produced by adapter layer.
#
# BOUNDARY:
#
#   ADAPTER ENGINE
#          |
#          v
#   ADAPTER AUDIT ARTIFACT
#          |
#          v
#   GOVERNANCE REVIEW
#
# MUST NOT:
#
#   - execute adapters
#   - perform conversions
#   - select adapter strategy
#   - interpret semantic meaning
#   - modify payloads
#   - repair failures
#   - mutate runtime state
#
# OWNERSHIP:
#
#   ADAPTER LAYER:
#       produces conversion evidence
#
#   AUDIT CONTRACT:
#       transports immutable artifact
#
#   GOVERNANCE:
#       evaluates evidence externally
#
# GUARANTEES:
#
#   - immutable state
#   - deterministic structure
#   - explicit evidence boundary
#   - zero hidden mutation paths
#
# STATUS:
#
#   GK STRICT
#   PURE CONTRACT
#   AUDIT BOUNDARY
#
# ============================================================


from __future__ import annotations


from dataclasses import dataclass
from typing import (
    Final,
    Tuple,
)



__all__ = [
    "VERSION",
    "AdapterAuditError",
    "AdapterAuditEntry",
    "AdapterReportAudit",
]



VERSION: Final[str] = (
    "AdapterReportAuditContract v6.3"
)



# ============================================================
# CONTROLLED FAILURE
# ============================================================


class AdapterAuditError(Exception):
    """
    Adapter audit structural artifact failure.

    Represents:

        invalid contract structure only.

    Does not represent:

        adapter failures,
        conversion failures,
        runtime failures.
    """

    pass



# ============================================================
# ADAPTER AUDIT ENTRY
# ============================================================


@dataclass(
    frozen=True,
    slots=True,
)
class AdapterAuditEntry:
    """
    Immutable adapter evidence record.

    Represents:

        observed adapter conversion fact.

    Does not represent:

        semantic correctness,
        business decision,
        recovery action.
    """


    adapter_name: str

    input_type: str

    output_type: str

    status: str

    message: str = ""



    def __post_init__(
        self,
    ) -> None:


        for name, value in (
            ("adapter_name", self.adapter_name),
            ("input_type", self.input_type),
            ("output_type", self.output_type),
            ("status", self.status),
            ("message", self.message),
        ):

            if not isinstance(
                value,
                str,
            ):
                raise AdapterAuditError(
                    f"{name.upper()}_MUST_BE_STRING"
                )


            if name != "message":

                if not value.strip():

                    raise AdapterAuditError(
                        f"{name.upper()}_EMPTY"
                    )



# ============================================================
# AUDIT REPORT CONTRACT
# ============================================================


@dataclass(
    frozen=True,
    slots=True,
)
class AdapterReportAudit:
    """
    Immutable adapter audit report.

    Contains:

        - adapter identity
        - source contract reference
        - conversion observations

    Does not:

        - execute adapters
        - validate adapter correctness
        - mutate pipeline state
    """


    version: str

    source_contract_version: str

    adapter: str


    entries: Tuple[
        AdapterAuditEntry,
        ...
    ]



    def __post_init__(
        self,
    ) -> None:


        for name, value in (
            ("version", self.version),
            (
                "source_contract_version",
                self.source_contract_version,
            ),
            ("adapter", self.adapter),
        ):

            if not isinstance(
                value,
                str,
            ):
                raise AdapterAuditError(
                    f"{name.upper()}_MUST_BE_STRING"
                )


            if not value.strip():

                raise AdapterAuditError(
                    f"{name.upper()}_EMPTY"
                )



        if not isinstance(
            self.entries,
            tuple,
        ):

            raise AdapterAuditError(
                "ENTRIES_MUST_BE_TUPLE"
            )



        for entry in self.entries:

            if not isinstance(
                entry,
                AdapterAuditEntry,
            ):

                raise AdapterAuditError(
                    "INVALID_ADAPTER_AUDIT_ENTRY"
                )



# ============================================================
# READ HELPERS
# ============================================================


    @property
    def entry_count(
        self,
    ) -> int:
        """
        Deterministic observation count.
        """

        return len(
            self.entries
        )



    @property
    def passed(
        self,
    ) -> bool:
        """
        Evidence state projection.

        Does not evaluate adapter correctness.
        """

        return all(
            entry.status.upper() == "OK"
            for entry in self.entries
        )

#~~~~~~[FILE END: adapter_report_audit.py ]~~~~~~#

