# ============================================================
# CONTROLLED FAILURES
# ============================================================


class AmbiguityAuditError(Exception):
    """
    Ambiguity audit contract violation.

    Structural artifact failure only.
    """

    pass



# ============================================================
# CANDIDATE EVIDENCE
# ============================================================


@dataclass(
    frozen=True,
    slots=True,
)
class AmbiguityCandidateAudit:
    """
    Immutable ambiguity candidate observation.

    Represents possible interpretation
    detected by ingestion layer.

    Does not represent:
        - selected resolution
        - semantic decision
    """

    value: str

    confidence: float



    def __post_init__(
        self,
    ) -> None:


        if not isinstance(
            self.value,
            str,
        ):
            raise AmbiguityAuditError(
                "CANDIDATE_VALUE_MUST_BE_STRING"
            )


        if not self.value.strip():

            raise AmbiguityAuditError(
                "CANDIDATE_VALUE_EMPTY"
            )


        if not isinstance(
            self.confidence,
            (float, int),
        ):

            raise AmbiguityAuditError(
                "CONFIDENCE_MUST_BE_NUMERIC"
            )


        if (
            self.confidence < 0.0
            or self.confidence > 1.0
        ):

            raise AmbiguityAuditError(
                "CONFIDENCE_OUT_OF_RANGE"
            )



# ============================================================
# AMBIGUITY EVENT
# ============================================================


@dataclass(
    frozen=True,
    slots=True,
)
class AmbiguityEventAudit:
    """
    Immutable ambiguity detection event.

    Represents ambiguity evidence only.
    """

    field: str

    reason: str

    candidates: Tuple[
        AmbiguityCandidateAudit,
        ...
    ]



    def __post_init__(
        self,
    ) -> None:


        if not isinstance(
            self.field,
            str,
        ):

            raise AmbiguityAuditError(
                "FIELD_MUST_BE_STRING"
            )


        if not self.field.strip():

            raise AmbiguityAuditError(
                "FIELD_EMPTY"
            )


        if not isinstance(
            self.reason,
            str,
        ):

            raise AmbiguityAuditError(
                "REASON_MUST_BE_STRING"
            )


        if not self.reason.strip():

            raise AmbiguityAuditError(
                "REASON_EMPTY"
            )


        if not isinstance(
            self.candidates,
            tuple,
        ):

            raise AmbiguityAuditError(
                "CANDIDATES_MUST_BE_TUPLE"
            )


        for candidate in self.candidates:

            if not isinstance(
                candidate,
                AmbiguityCandidateAudit,
            ):

                raise AmbiguityAuditError(
                    "INVALID_CANDIDATE"
                )



# ============================================================
# REPORT
# ============================================================


@dataclass(
    frozen=True,
    slots=True,
)
class AmbiguityReportAudit:
    """
    Immutable ambiguity audit report.

    Contains:
        - ambiguity evidence
        - detected candidate observations

    Does not:
        - resolve ambiguity
        - select candidates
        - mutate ingestion state
    """

    source: str

    events: Tuple[
        AmbiguityEventAudit,
        ...
    ]

    version: str = VERSION



    def __post_init__(
        self,
    ) -> None:


        if not isinstance(
            self.source,
            str,
        ):

            raise AmbiguityAuditError(
                "SOURCE_MUST_BE_STRING"
            )


        if not self.source.strip():

            raise AmbiguityAuditError(
                "SOURCE_EMPTY"
            )


        if not isinstance(
            self.events,
            tuple,
        ):

            raise AmbiguityAuditError(
                "EVENTS_MUST_BE_TUPLE"
            )


        for event in self.events:

            if not isinstance(
                event,
                AmbiguityEventAudit,
            ):

                raise AmbiguityAuditError(
                    "INVALID_AMBIGUITY_EVENT"
                )



# ============================================================
# READ HELPERS
# ============================================================


    @property
    def event_count(
        self,
    ) -> int:
        """
        Deterministic event count.
        """

        return len(
            self.events
        )

