from __future__ import annotations

from dataclasses import dataclass
from typing import Final


__all__ = [
    "VERSION",
    "AuditAccessAttemptContractError",
    "AuditAccessAttemptContract",
]

VERSION: Final[str] = "AuditAccessAttemptContract v6.3"


class AuditAccessAttemptContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class AuditAccessAttemptContract:
    actor_ip_address: str
    target_resource_id: str
    is_granted: bool
    denial_reason: str
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.actor_ip_address, str):
            raise AuditAccessAttemptContractError("ACTOR_IP_ADDRESS_MUST_BE_STRING")
        if not self.actor_ip_address.strip():
            raise AuditAccessAttemptContractError("ACTOR_IP_ADDRESS_EMPTY")

        if not isinstance(self.target_resource_id, str):
            raise AuditAccessAttemptContractError("TARGET_RESOURCE_ID_MUST_BE_STRING")
        if not self.target_resource_id.strip():
            raise AuditAccessAttemptContractError("TARGET_RESOURCE_ID_EMPTY")

        if not isinstance(self.is_granted, bool):
            raise AuditAccessAttemptContractError("IS_GRANTED_MUST_BE_BOOL")

        if not isinstance(self.denial_reason, str):
            raise AuditAccessAttemptContractError("DENIAL_REASON_MUST_BE_STRING")
        if not self.is_granted and not self.denial_reason.strip():
            raise AuditAccessAttemptContractError("DENIAL_REASON_REQUIRED_IF_NOT_GRANTED")

        if not isinstance(self.version, str):
            raise AuditAccessAttemptContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise AuditAccessAttemptContractError("VERSION_EMPTY")

