    time_window_seconds: int
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.attacker_ip_address, str):
            raise AuditBruteForceAttemptContractError("ATTACKER_IP_ADDRESS_MUST_BE_STRING")
