@dataclass(frozen=True, slots=True)
class AuditPciDssEnvironmentScanContract:
    scan_id: str
    target_cde_subnet: str
    high_vulnerabilities_found: int
    is_scan_passed: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.scan_id, str):
            raise AuditPciDssEnvironmentScanContractError("SCAN_ID_MUST_BE_STRING")
        if not self.scan_id.strip():
            raise AuditPciDssEnvironmentScanContractError("SCAN_ID_EMPTY")

        if not isinstance(self.target_cde_subnet, str):
            raise AuditPciDssEnvironmentScanContractError("TARGET_CDE_SUBNET_MUST_BE_STRING")
        if not self.target_cde_subnet.strip():
            raise AuditPciDssEnvironmentScanContractError("TARGET_CDE_SUBNET_EMPTY")

        if not isinstance(self.high_vulnerabilities_found, int):
            raise AuditPciDssEnvironmentScanContractError("HIGH_VULNERABILITIES_FOUND_MUST_BE_INT")
        if self.high_vulnerabilities_found < 0:
            raise AuditPciDssEnvironmentScanContractError("HIGH_VULNERABILITIES_FOUND_MUST_BE_NON_NEGATIVE")

        if not isinstance(self.is_scan_passed, bool):
            raise AuditPciDssEnvironmentScanContractError("IS_SCAN_PASSED_MUST_BE_BOOL")
            
        if self.high_vulnerabilities_found > 0 and self.is_scan_passed:
            raise AuditPciDssEnvironmentScanContractError("SCAN_CANNOT_PASS_WITH_HIGH_VULNERABILITIES")

        if not isinstance(self.version, str):
            raise AuditPciDssEnvironmentScanContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise AuditPciDssEnvironmentScanContractError("VERSION_EMPTY")

