class AuditResultContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class AuditResultContract:
    audit_job_id: str
    is_compliant: bool
    violating_log_ids: Sequence[str]
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.audit_job_id, str):
            raise AuditResultContractError("AUDIT_JOB_ID_MUST_BE_STRING")
        if not self.audit_job_id.strip():
            raise AuditResultContractError("AUDIT_JOB_ID_EMPTY")

        if not isinstance(self.is_compliant, bool):
            raise AuditResultContractError("IS_COMPLIANT_MUST_BE_BOOL")

        if not isinstance(self.violating_log_ids, Sequence):
            raise AuditResultContractError("VIOLATING_LOG_IDS_MUST_BE_SEQUENCE")
        for log_id in self.violating_log_ids:
            if not isinstance(log_id, str):
                raise AuditResultContractError("VIOLATING_LOG_IDS_MUST_CONTAIN_STRINGS")

        if not self.is_compliant and len(self.violating_log_ids) == 0:
            raise AuditResultContractError("NON_COMPLIANT_MUST_HAVE_VIOLATING_LOGS")

        if not isinstance(self.version, str):
            raise AuditResultContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise AuditResultContractError("VERSION_EMPTY")

#~~~~~~[FILE END: audit_result_contract.py ]~~~~~~#

