from __future__ import annotations

from dataclasses import dataclass
from typing import Final, Sequence


__all__ = [
    "VERSION",
    "AuditVulnerabilityScanResultContractError",
    "AuditVulnerabilityScanResultContract",
]

VERSION: Final[str] = "AuditVulnerabilityScanResultContract v6.3"


class AuditVulnerabilityScanResultContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class AuditVulnerabilityScanResultContract:
    target_image_uri: str
    discovered_cves: Sequence[str]  # e.g., ['CVE-2021-44228']
    critical_count: int
    is_deployment_blocked: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.target_image_uri, str):
            raise AuditVulnerabilityScanResultContractError("TARGET_IMAGE_URI_MUST_BE_STRING")
        if not self.target_image_uri.strip():
            raise AuditVulnerabilityScanResultContractError("TARGET_IMAGE_URI_EMPTY")

        if not isinstance(self.discovered_cves, Sequence):
            raise AuditVulnerabilityScanResultContractError("DISCOVERED_CVES_MUST_BE_SEQUENCE")
        for cve in self.discovered_cves:
            if not isinstance(cve, str):
                raise AuditVulnerabilityScanResultContractError("DISCOVERED_CVES_MUST_CONTAIN_STRINGS")

        if not isinstance(self.critical_count, int):
            raise AuditVulnerabilityScanResultContractError("CRITICAL_COUNT_MUST_BE_INT")
        if self.critical_count < 0:
            raise AuditVulnerabilityScanResultContractError("CRITICAL_COUNT_MUST_BE_NON_NEGATIVE")

        if not isinstance(self.is_deployment_blocked, bool):
            raise AuditVulnerabilityScanResultContractError("IS_DEPLOYMENT_BLOCKED_MUST_BE_BOOL")
        if self.critical_count > 0 and not self.is_deployment_blocked:
            raise AuditVulnerabilityScanResultContractError("DEPLOYMENT_MUST_BE_BLOCKED_IF_CRITICAL_CVES_EXIST")

        if not isinstance(self.version, str):
            raise AuditVulnerabilityScanResultContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise AuditVulnerabilityScanResultContractError("VERSION_EMPTY")

#~~~~~~[FILE END: audit_vulnerability_scan_result_contract.py ]~~~~~~#

