class DateParserAuditError(Exception):
    """
    Date parser audit contract violation.

    Structural artifact failure only.
    """

    pass



@dataclass(
    frozen=True,
    slots=True,
)
class DateParseObservation:
    """
    Immutable parser evidence record.

    Contains observation only.
    """

    field: str

    detected_format: str

    status: str

    sample_count: int = 0


    def __post_init__(self) -> None:

        for name, value in (
            ("field", self.field),
            ("detected_format", self.detected_format),
            ("status", self.status),
        ):

            if not isinstance(value, str):

                raise DateParserAuditError(
                    f"{name.upper()}_MUST_BE_STRING"
                )


            if not value.strip():

                raise DateParserAuditError(
                    f"{name.upper()}_EMPTY"
                )


        if isinstance(
            self.sample_count,
            bool,
        ):

            raise DateParserAuditError(
                "SAMPLE_COUNT_BOOL_FORBIDDEN"
            )


        if not isinstance(
            self.sample_count,
            int,
        ):

            raise DateParserAuditError(
                "SAMPLE_COUNT_MUST_BE_INT"
            )


        if self.sample_count < 0:

            raise DateParserAuditError(
                "SAMPLE_COUNT_NEGATIVE"
            )



@dataclass(
    frozen=True,
    slots=True,
)
class DateParserReportAudit:
    """
    Deep immutable date parser audit artifact.

    Contains:

        - parser identity
        - immutable observations

    Does not:

        - execute parser
        - interpret dates
        - mutate pipeline state
    """

    source_contract_version: str

    parser_name: str

    observations: Tuple[
        DateParseObservation,
        ...
    ]

    version: str = VERSION



    def __post_init__(self) -> None:


        if not isinstance(
            self.source_contract_version,
            str,
        ):

            raise DateParserAuditError(
                "SOURCE_VERSION_MUST_BE_STRING"
            )


        if not isinstance(
            self.parser_name,
            str,
        ):

            raise DateParserAuditError(
                "PARSER_NAME_MUST_BE_STRING"
            )


        if not self.parser_name.strip():

            raise DateParserAuditError(
                "PARSER_NAME_EMPTY"
            )


        if not isinstance(
            self.observations,
            tuple,
        ):

            raise DateParserAuditError(
                "OBSERVATIONS_MUST_BE_TUPLE"
            )


        for item in self.observations:

            if not isinstance(
                item,
                DateParseObservation,
            ):

                raise DateParserAuditError(
                    "INVALID_DATE_OBSERVATION"
                )



    @property
    def observation_count(
        self,
    ) -> int:

        return len(
            self.observations
        )



    @property
    def passed(
        self,
    ) -> bool:

        return all(
            item.status.upper() == "OK"
            for item in self.observations
        )

