# ============================================================
# IMMUTABLE METADATA
# ============================================================


def _freeze_metadata(
    value: Mapping[str, Any] | None,
) -> Mapping[str, Any] | None:
    """
    Converts metadata into immutable mapping boundary.

    Audit metadata is evidence only.
    No mutable payload ownership allowed.
    """

    if value is None:
        return None

    if not isinstance(
        value,
        Mapping,
    ):
        raise IngestionBatchAuditSummaryError(
            "METADATA_MUST_BE_MAPPING"
        )

    return MappingProxyType(
        dict(value)
    )



