@dataclass(
    frozen=True,
    slots=True,
)
class IngestionBatchAuditSummary:
    """
    Immutable ingestion batch audit aggregation artifact.

    Represents:

        deterministic evidence state of one ingestion batch.

    Does not represent:

        execution result,
        business correctness,
        remediation decision.
    """


    batch_id: str

    pipeline_id: str

    stages: Tuple[
        AuditStageReference,
        ...
    ]

    status: str

    metadata: Mapping[
        str,
        Any,
    ] | None = None

    version: str = VERSION



    def __post_init__(
        self,
    ) -> None:


        for name, value in (
            (
                "batch_id",
                self.batch_id,
            ),
            (
                "pipeline_id",
                self.pipeline_id,
            ),
            (
                "status",
                self.status,
            ),
            (
                "version",
                self.version,
            ),
        ):

            if not isinstance(
                value,
                str,
            ):
                raise IngestionBatchAuditSummaryError(
                    f"{name.upper()}_MUST_BE_STRING"
                )


            if not value.strip():

                raise IngestionBatchAuditSummaryError(
                    f"{name.upper()}_EMPTY"
                )



        if not isinstance(
            self.stages,
            tuple,
        ):

            raise IngestionBatchAuditSummaryError(
                "STAGES_MUST_BE_TUPLE"
            )



        for stage in self.stages:

            if not isinstance(
                stage,
                AuditStageReference,
            ):

                raise IngestionBatchAuditSummaryError(
                    "INVALID_STAGE_REFERENCE"
                )



        if self.metadata is not None:

            frozen_metadata = _freeze_metadata(
                self.metadata
            )

            object.__setattr__(
                self,
                "metadata",
                frozen_metadata,
            )



# ============================================================
# READ HELPERS
# ============================================================


    @property
    def stage_count(
        self,
    ) -> int:
        """
        Deterministic number of aggregated audit stages.
        """

        return len(
            self.stages
        )



    def stage_names(
        self,
    ) -> Tuple[str, ...]:
        """
        Returns deterministic stage identity list.
        """

        return tuple(
            stage.stage_name
            for stage in self.stages
        )



    @property
    def completed(
        self,
    ) -> bool:
        """
        Returns recorded batch lifecycle state.

        Does not evaluate ingestion correctness.
        """

        return (
            self.status.upper()
            in {
                "COMPLETED",
                "SUCCESS",
                "FAILED",
            }
        )

