    def __post_init__(
        self,
    ) -> None:


        _validate_string(
            "batch_id",
            self.batch_id,
        )


        _validate_string(
            "created_by",
            self.created_by,
        )


        if not isinstance(
            self.entries,
            tuple,
        ):
            raise IngestionQuarantineAuditError(
                "ENTRIES_MUST_BE_TUPLE"
            )


        for entry in self.entries:

            if not isinstance(
                entry,
                QuarantineEntry,
            ):
                raise IngestionQuarantineAuditError(
                    "INVALID_QUARANTINE_ENTRY"
                )


        _validate_mapping(
            self.metadata,
        )


        if not isinstance(
            self.version,
            str,
        ):
            raise IngestionQuarantineAuditError(
                "VERSION_MUST_BE_STRING"
            )



