# ============================================================
# CONTROLLED FAILURE
# ============================================================


class NormalizationAuditError(Exception):
    """
    Normalization audit contract violation.

    Structural artifact failure only.
    """

    pass



# ============================================================
# IMMUTABILITY HELPERS
# ============================================================


def _validate_string(
    name: str,
    value: Any,
) -> None:

    if not isinstance(
        value,
        str,
    ):
        raise NormalizationAuditError(
            f"{name.upper()}_MUST_BE_STRING"
        )


    if not value.strip():

        raise NormalizationAuditError(
            f"{name.upper()}_EMPTY"
        )



# ============================================================
# OBSERVATION CONTRACT
# ============================================================


@dataclass(
    frozen=True,
    slots=True,
)
class NormalizationObservation:
    """
    Immutable normalization evidence record.

    Represents:

        observed normalization event.

    Does not represent:

        normalization execution,
        normalization policy,
        semantic correctness.
    """


    field: str

    operation: str

    status: str

    original_type: str | None = None

    normalized_type: str | None = None



    def __post_init__(
        self,
    ) -> None:


        for name, value in (
            (
                "field",
                self.field,
            ),
            (
                "operation",
                self.operation,
            ),
            (
                "status",
                self.status,
            ),
        ):

            _validate_string(
                name,
                value,
            )


        for name, value in (
            (
                "original_type",
                self.original_type,
            ),
            (
                "normalized_type",
                self.normalized_type,
            ),
        ):

            if value is not None:

                _validate_string(
                    name,
                    value,
                )



# ============================================================
# REPORT CONTRACT
# ============================================================


@dataclass(
    frozen=True,
    slots=True,
)
class NormalizationReportAudit:
    """
    Immutable normalization audit artifact.

    Contains:

        - normalization observations
        - evidence metadata
        - source contract identity

    Does not:

        - execute normalization
        - decide normalization rules
        - validate business correctness
    """


    source_contract_version: str

    normalizer_name: str


    observations: Tuple[
        NormalizationObservation,
        ...
    ]


    metadata: Mapping[
        str,
        Any,
    ] | None = None


    version: str = VERSION



    def __post_init__(
        self,
    ) -> None:


        _validate_string(
            "source_contract_version",
            self.source_contract_version,
        )


        _validate_string(
            "normalizer_name",
            self.normalizer_name,
        )


        if not isinstance(
            self.observations,
            tuple,
        ):
            raise NormalizationAuditError(
                "OBSERVATIONS_MUST_BE_TUPLE"
            )


        for observation in self.observations:

            if not isinstance(
                observation,
                NormalizationObservation,
            ):
                raise NormalizationAuditError(
                    "INVALID_NORMALIZATION_OBSERVATION"
                )


        if self.metadata is not None:

            if not isinstance(
                self.metadata,
                Mapping,
            ):
                raise NormalizationAuditError(
                    "METADATA_MUST_BE_MAPPING"
                )


        _validate_string(
            "version",
            self.version,
        )



# ============================================================
# READ HELPERS
# ============================================================


    @property
    def observation_count(
        self,
    ) -> int:
        """
        Deterministic observation count.
        """

        return len(
            self.observations
        )



    @property
    def passed(
        self,
    ) -> bool:
        """
        Evidence completion state.

        Does not evaluate semantic correctness.
        """

        return all(
            item.status.upper() == "OK"
            for item in self.observations
        )



    def fields(
        self,
    ) -> Tuple[str, ...]:
        """
        Deterministic normalized field identity list.
        """

        return tuple(
            item.field
            for item in self.observations
        )



    def operations(
        self,
    ) -> Tuple[str, ...]:
        """
        Deterministic normalization operation list.
        """

        return tuple(
            item.operation
            for item in self.observations
        )

