# ============================================================
# MAPPING OBSERVATION CONTRACT
# ============================================================


@dataclass(
    frozen=True,
    slots=True,
)
class OntologyMappingObservation:
    """
    Immutable ontology mapping evidence.

    Represents:

        observed relation between
        ingestion field and ontology identifier.

    Does not represent:

        ontology resolution,
        semantic correctness,
        business interpretation.
    """


    field: str

    ontology_id: str

    status: str

    confidence: float | None = None



    def __post_init__(
        self,
    ) -> None:


        for name, value in (
            (
                "field",
                self.field,
            ),
            (
                "ontology_id",
                self.ontology_id,
            ),
            (
                "status",
                self.status,
            ),
        ):

            _validate_string(
                name,
                value,
            )


        if self.confidence is not None:

            if not isinstance(
                self.confidence,
                float,
            ):
                raise OntologyAuditError(
                    "CONFIDENCE_MUST_BE_FLOAT"
                )


            if (
                self.confidence < 0.0
                or self.confidence > 1.0
            ):
                raise OntologyAuditError(
                    "CONFIDENCE_OUT_OF_RANGE"
                )



