# ============================================================
# FIELD OBSERVATION
# ============================================================


@dataclass(
    frozen=True,
    slots=True,
)
class InferredFieldObservation:
    """
    Immutable inferred field evidence.

    Represents:

        observed inference result

    Does not represent:

        semantic correctness.
    """


    field_id: str

    inferred_type: str

    confidence: float

    diagnostics: Tuple[
        str,
        ...
    ]



    def __post_init__(
        self,
    ) -> None:

        for name, value in (
            (
                "field_id",
                self.field_id,
            ),
            (
                "inferred_type",
                self.inferred_type,
            ),
        ):

            if not isinstance(
                value,
                str,
            ):
                raise SchemaInferenceAuditError(
                    f"{name.upper()}_MUST_BE_STRING"
                )


            if not value.strip():

                raise SchemaInferenceAuditError(
                    f"{name.upper()}_EMPTY"
                )


        if not isinstance(
            self.confidence,
            float,
        ):
            raise SchemaInferenceAuditError(
                "CONFIDENCE_MUST_BE_FLOAT"
            )


        if (
            self.confidence < 0.0
            or self.confidence > 1.0
        ):
            raise SchemaInferenceAuditError(
                "CONFIDENCE_OUT_OF_RANGE"
            )


        if not isinstance(
            self.diagnostics,
            tuple,
        ):
            raise SchemaInferenceAuditError(
                "DIAGNOSTICS_MUST_BE_TUPLE"
            )



# ============================================================
# STRUCTURAL LINEAGE
# ============================================================


@dataclass(
    frozen=True,
    slots=True,
)
class StructuralLineageEvidence:
    """
    Immutable structure lineage evidence.
    """


    path: str

    depth: int

    parent: str | None = None



    def __post_init__(
        self,
    ) -> None:

        if not isinstance(
            self.path,
            str,
        ):
            raise SchemaInferenceAuditError(
                "PATH_MUST_BE_STRING"
            )


        if not self.path.strip():

            raise SchemaInferenceAuditError(
                "PATH_EMPTY"
            )


        if not isinstance(
            self.depth,
            int,
        ):
            raise SchemaInferenceAuditError(
                "DEPTH_MUST_BE_INT"
            )


        if self.depth < 0:

            raise SchemaInferenceAuditError(
                "DEPTH_NEGATIVE"
            )


        if self.parent is not None:

            if not isinstance(
                self.parent,
                str,
            ):
                raise SchemaInferenceAuditError(
                    "PARENT_MUST_BE_STRING"
                )



