# ============================================================


@dataclass(
    frozen=True,
    slots=True,
)
class SchemaInferenceAuditReport:
    """
    Immutable schema inference audit artifact.

    Contains:

        - field observations
        - lineage evidence
        - diagnostics
        - metric references

    Does not:

        - infer schemas
        - validate semantics
        - normalize output
        - execute recovery
    """


    source_contract_version: str

    observations: Tuple[
        InferredFieldObservation,
        ...
    ]

    lineage: Tuple[
        StructuralLineageEvidence,
        ...
    ]

    diagnostics: Tuple[
        InferenceDiagnostic,
        ...
    ]

    metrics: Mapping[
        str,
        Any,
    ] | None = None


    version: str = VERSION



    def __post_init__(
        self,
    ) -> None:


        if not isinstance(
            self.source_contract_version,
            str,
        ):
            raise SchemaInferenceAuditError(
                "SOURCE_VERSION_MUST_BE_STRING"
            )


        for name, value in (
            (
                "observations",
                self.observations,
            ),
            (
                "lineage",
                self.lineage,
            ),
            (
                "diagnostics",
                self.diagnostics,
            ),
        ):

            if not isinstance(
                value,
                tuple,
            ):
                raise SchemaInferenceAuditError(
                    f"{name.upper()}_MUST_BE_TUPLE"
                )



        for item in self.observations:

            if not isinstance(
                item,
                InferredFieldObservation,
            ):
                raise SchemaInferenceAuditError(
                    "INVALID_FIELD_OBSERVATION"
                )



        for item in self.lineage:

            if not isinstance(
                item,
                StructuralLineageEvidence,
            ):
                raise SchemaInferenceAuditError(
                    "INVALID_LINEAGE_EVIDENCE"
                )



        for item in self.diagnostics:

            if not isinstance(
                item,
                InferenceDiagnostic,
            ):
                raise SchemaInferenceAuditError(
                    "INVALID_DIAGNOSTIC"
                )



        if self.metrics is not None:

            if not isinstance(
                self.metrics,
                Mapping,
            ):
                raise SchemaInferenceAuditError(
                    "METRICS_MUST_BE_MAPPING"
                )



# ============================================================
# READ HELPERS
# ============================================================


    @property
    def observation_count(
        self,
    ) -> int:
        """
        Deterministic observation count.
        """

        return len(
            self.observations
        )



    @property
    def lineage_count(
        self,
    ) -> int:
        """
        Deterministic lineage evidence count.
        """

        return len(
            self.lineage
        )



    @property
    def diagnostic_count(
        self,
    ) -> int:
        """
        Deterministic diagnostic count.
        """

        return len(
            self.diagnostics
        )

