# ============================================================
# TRANSFORMATION OBSERVATION
# ============================================================


@dataclass(
    frozen=True,
    slots=True,
)
class TransformationObservation:
    """
    Immutable transformation evidence record.

    Represents observed transformation facts only.
    """

    operation: str

    source_type: str

    target_type: str

    status: str

    affected_fields: Tuple[
        str,
        ...
    ] = ()



    def __post_init__(
        self,
    ) -> None:

        for name, value in (
            ("operation", self.operation),
            ("source_type", self.source_type),
            ("target_type", self.target_type),
            ("status", self.status),
        ):

            if not isinstance(
                value,
                str,
            ):
                raise TransformationAuditError(
                    f"{name.upper()}_MUST_BE_STRING"
                )


            if not value.strip():

                raise TransformationAuditError(
                    f"{name.upper()}_EMPTY"
                )



        if not isinstance(
            self.affected_fields,
            tuple,
        ):

            raise TransformationAuditError(
                "AFFECTED_FIELDS_MUST_BE_TUPLE"
            )



        for field in self.affected_fields:

            if not isinstance(
                field,
                str,
            ):

                raise TransformationAuditError(
                    "FIELD_NAME_MUST_BE_STRING"
                )


            if not field.strip():

                raise TransformationAuditError(
                    "FIELD_NAME_EMPTY"
                )



