@dataclass(frozen=True, slots=True)
class CanonicalColumnContract:
    column_name: str
    column_type: str
    cells: Sequence[CanonicalCellContract]
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.column_name, str):
            raise CanonicalColumnContractError("COLUMN_NAME_MUST_BE_STRING")
        if not self.column_name.strip():
            raise CanonicalColumnContractError("COLUMN_NAME_EMPTY")

        if not isinstance(self.column_type, str):
            raise CanonicalColumnContractError("COLUMN_TYPE_MUST_BE_STRING")
        if not self.column_type.strip():
            raise CanonicalColumnContractError("COLUMN_TYPE_EMPTY")

        if not isinstance(self.cells, Sequence):
            raise CanonicalColumnContractError("CELLS_MUST_BE_SEQUENCE")
        for cell in self.cells:
            if not isinstance(cell, CanonicalCellContract):
                raise CanonicalColumnContractError("CELLS_MUST_CONTAIN_CANONICAL_CELLS")

        if not isinstance(self.version, str):
            raise CanonicalColumnContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise CanonicalColumnContractError("VERSION_EMPTY")

