class CanonicalEntityContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class CanonicalEntityContract:
    entity_name: str
    business_domain: str  # e.g., 'SALES', 'HR'
    underlying_structure_id: str  # Link back to Table/Document/Node ID
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.entity_name, str):
            raise CanonicalEntityContractError("ENTITY_NAME_MUST_BE_STRING")
        if not self.entity_name.strip():
            raise CanonicalEntityContractError("ENTITY_NAME_EMPTY")

        if not isinstance(self.business_domain, str):
            raise CanonicalEntityContractError("BUSINESS_DOMAIN_MUST_BE_STRING")
        if not self.business_domain.strip():
            raise CanonicalEntityContractError("BUSINESS_DOMAIN_EMPTY")

        if not isinstance(self.underlying_structure_id, str):
            raise CanonicalEntityContractError("UNDERLYING_STRUCTURE_ID_MUST_BE_STRING")
        if not self.underlying_structure_id.strip():
            raise CanonicalEntityContractError("UNDERLYING_STRUCTURE_ID_EMPTY")

        if not isinstance(self.version, str):
            raise CanonicalEntityContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise CanonicalEntityContractError("VERSION_EMPTY")

