class CanonicalHeaderContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class CanonicalHeaderContract:
    ordered_column_names: Sequence[str]
    has_index_column: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.ordered_column_names, Sequence):
            raise CanonicalHeaderContractError("ORDERED_COLUMN_NAMES_MUST_BE_SEQUENCE")
