        if not isinstance(self.has_index_column, bool):
            raise CanonicalHeaderContractError("HAS_INDEX_COLUMN_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise CanonicalHeaderContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise CanonicalHeaderContractError("VERSION_EMPTY")

