class CanonicalLifecycleContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class CanonicalLifecycleContract:
    current_state: str  # e.g., 'PARSED', 'NORMALIZED', 'SEALED'
    is_read_only: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.current_state, str):
            raise CanonicalLifecycleContractError("CURRENT_STATE_MUST_BE_STRING")
        if self.current_state not in ("PARSED", "NORMALIZED", "VALIDATED", "SEALED", "ERROR"):
            raise CanonicalLifecycleContractError("CURRENT_STATE_MUST_BE_VALID_ENUM")

        if not isinstance(self.is_read_only, bool):
            raise CanonicalLifecycleContractError("IS_READ_ONLY_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise CanonicalLifecycleContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise CanonicalLifecycleContractError("VERSION_EMPTY")

