class CanonicalNullContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class CanonicalNullContract:
    null_reason: str  # e.g., 'MISSING', 'NOT_APPLICABLE', 'REDACTED'
    original_representation: str | None  # e.g., 'NaN', 'NULL', ''
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.null_reason, str):
            raise CanonicalNullContractError("NULL_REASON_MUST_BE_STRING")
        if not self.null_reason.strip():
            raise CanonicalNullContractError("NULL_REASON_EMPTY")

        if self.original_representation is not None and not isinstance(self.original_representation, str):
            raise CanonicalNullContractError("ORIGINAL_REPRESENTATION_MUST_BE_STRING_OR_NONE")

        if not isinstance(self.version, str):
            raise CanonicalNullContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise CanonicalNullContractError("VERSION_EMPTY")

