#
#   GK STRICT
#   PURE CONTRACT
#   CANONICAL BOUNDARY
#
# ============================================================

from __future__ import annotations

from dataclasses import dataclass
from typing import Final, Sequence, Any

from .canonical_context_contract import CanonicalContextContract
from .canonical_diagnostic_contract import CanonicalDiagnosticContract
from .canonical_lifecycle_contract import CanonicalLifecycleContract


__all__ = [
    "VERSION",
    "CanonicalResultContractError",
    "CanonicalResultContract",
]

VERSION: Final[str] = "CanonicalResultContract v6.3"


class CanonicalResultContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class CanonicalResultContract:
    run_id: str
    context: CanonicalContextContract
    lifecycle: CanonicalLifecycleContract
    canonical_structure: Any  # Should be Table, Graph, Document, Tensor, etc.
    diagnostics: Sequence[CanonicalDiagnosticContract]
    is_success: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.run_id, str):
            raise CanonicalResultContractError("RUN_ID_MUST_BE_STRING")
        if not self.run_id.strip():
            raise CanonicalResultContractError("RUN_ID_EMPTY")

        if not isinstance(self.context, CanonicalContextContract):
            raise CanonicalResultContractError("CONTEXT_MUST_BE_CONTRACT")

        if not isinstance(self.lifecycle, CanonicalLifecycleContract):
            raise CanonicalResultContractError("LIFECYCLE_MUST_BE_CONTRACT")

        if self.canonical_structure is None:
            raise CanonicalResultContractError("CANONICAL_STRUCTURE_CANNOT_BE_NONE")

        if not isinstance(self.diagnostics, Sequence):
            raise CanonicalResultContractError("DIAGNOSTICS_MUST_BE_SEQUENCE")
        for diag in self.diagnostics:
            if not isinstance(diag, CanonicalDiagnosticContract):
                raise CanonicalResultContractError("DIAGNOSTICS_MUST_CONTAIN_CONTRACTS")

        if not isinstance(self.is_success, bool):
            raise CanonicalResultContractError("IS_SUCCESS_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise CanonicalResultContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise CanonicalResultContractError("VERSION_EMPTY")

#~~~~~~[FILE END: canonical_result_contract.py ]~~~~~~#

