class DetectionCardinalityContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class DetectionCardinalityContract:
    distinct_count: int
    is_estimated: bool
    uniqueness_ratio: float
    is_primary_key_candidate: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.distinct_count, int):
            raise DetectionCardinalityContractError("DISTINCT_COUNT_MUST_BE_INT")
        if self.distinct_count < 0:
            raise DetectionCardinalityContractError("DISTINCT_COUNT_MUST_BE_NON_NEGATIVE")

        if not isinstance(self.is_estimated, bool):
            raise DetectionCardinalityContractError("IS_ESTIMATED_MUST_BE_BOOL")

        if not isinstance(self.uniqueness_ratio, float):
            raise DetectionCardinalityContractError("UNIQUENESS_RATIO_MUST_BE_FLOAT")
        if not (0.0 <= self.uniqueness_ratio <= 1.0):
            raise DetectionCardinalityContractError("UNIQUENESS_RATIO_MUST_BE_BETWEEN_0_AND_1")

        if not isinstance(self.is_primary_key_candidate, bool):
            raise DetectionCardinalityContractError("IS_PRIMARY_KEY_CANDIDATE_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise DetectionCardinalityContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise DetectionCardinalityContractError("VERSION_EMPTY")

#~~~~~~[FILE END: detection_cardinality_contract.py ]~~~~~~#

