class DetectionCorrelationContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class DetectionCorrelationContract:
    field_a: str
    field_b: str
    correlation_method: str  # e.g., 'PEARSON', 'SPEARMAN', 'CRAMERS_V'
    correlation_value: float
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.field_a, str):
            raise DetectionCorrelationContractError("FIELD_A_MUST_BE_STRING")
        if not self.field_a.strip():
            raise DetectionCorrelationContractError("FIELD_A_EMPTY")

        if not isinstance(self.field_b, str):
            raise DetectionCorrelationContractError("FIELD_B_MUST_BE_STRING")
        if not self.field_b.strip():
            raise DetectionCorrelationContractError("FIELD_B_EMPTY")

        if self.field_a == self.field_b:
            raise DetectionCorrelationContractError("CANNOT_CORRELATE_FIELD_WITH_ITSELF")

        if not isinstance(self.correlation_method, str):
            raise DetectionCorrelationContractError("CORRELATION_METHOD_MUST_BE_STRING")
        if not self.correlation_method.strip():
            raise DetectionCorrelationContractError("CORRELATION_METHOD_EMPTY")

        if not isinstance(self.correlation_value, float):
            raise DetectionCorrelationContractError("CORRELATION_VALUE_MUST_BE_FLOAT")
        if not (-1.0 <= self.correlation_value <= 1.0):
            raise DetectionCorrelationContractError("CORRELATION_VALUE_MUST_BE_BETWEEN_MINUS_1_AND_1")

        if not isinstance(self.version, str):
            raise DetectionCorrelationContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise DetectionCorrelationContractError("VERSION_EMPTY")

#~~~~~~[FILE END: detection_correlation_contract.py ]~~~~~~#

