class DetectionDistributionContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class DetectionDistributionContract:
    min_value: float
    max_value: float
    mean: float
    standard_deviation: float
    skewness: float
    kurtosis: float
    version: str = VERSION

    def __post_init__(self) -> None:
        for field_name, value in (
            ("min_value", self.min_value),
            ("max_value", self.max_value),
            ("mean", self.mean),
            ("standard_deviation", self.standard_deviation),
            ("skewness", self.skewness),
            ("kurtosis", self.kurtosis),
        ):
            if not isinstance(value, float):
                raise DetectionDistributionContractError(f"{field_name.upper()}_MUST_BE_FLOAT")

        if self.min_value > self.max_value:
            raise DetectionDistributionContractError("MIN_VALUE_CANNOT_EXCEED_MAX_VALUE")

        if not isinstance(self.version, str):
            raise DetectionDistributionContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise DetectionDistributionContractError("VERSION_EMPTY")

