#   detection_frequency_contract.py
#
# Layer:
#   CORE / CONTRACTS / DETECTION
#
# ROLE:
#
#   Immutable detection categorical frequency atom.
#
# PURPOSE:
#
#   Records top-k (heavy hitters) values and their relative
#   frequencies, essential for Data Profiling of categorical fields.
#
# STATUS:
#
#   GK STRICT
#   PURE CONTRACT
#   DETECTION BOUNDARY
#
# ============================================================

from __future__ import annotations

from dataclasses import dataclass
from typing import Final, Sequence


__all__ = [
    "VERSION",
    "DetectionFrequencyContractError",
    "DetectionFrequencyContract",
]

VERSION: Final[str] = "DetectionFrequencyContract v6.3"


class DetectionFrequencyContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class DetectionFrequencyContract:
    top_k_values: Sequence[str]
    top_k_frequencies: Sequence[float]
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.top_k_values, Sequence):
            raise DetectionFrequencyContractError("TOP_K_VALUES_MUST_BE_SEQUENCE")
        
        for val in self.top_k_values:
            if not isinstance(val, str):
                raise DetectionFrequencyContractError("TOP_K_VALUES_MUST_CONTAIN_STRINGS")

        if not isinstance(self.top_k_frequencies, Sequence):
            raise DetectionFrequencyContractError("TOP_K_FREQUENCIES_MUST_BE_SEQUENCE")
            
        for freq in self.top_k_frequencies:
            if not isinstance(freq, float):
                raise DetectionFrequencyContractError("TOP_K_FREQUENCIES_MUST_CONTAIN_FLOATS")
            if not (0.0 <= freq <= 1.0):
                raise DetectionFrequencyContractError("TOP_K_FREQUENCIES_MUST_BE_BETWEEN_0_AND_1")

        if len(self.top_k_values) != len(self.top_k_frequencies):
            raise DetectionFrequencyContractError("TOP_K_VALUES_AND_FREQUENCIES_LENGTH_MISMATCH")

        if not isinstance(self.version, str):
            raise DetectionFrequencyContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise DetectionFrequencyContractError("VERSION_EMPTY")

#~~~~~~[FILE END: detection_frequency_contract.py ]~~~~~~#

