VERSION: Final[str] = "DetectionFunctionalDependencyContract v6.3"


class DetectionFunctionalDependencyContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class DetectionFunctionalDependencyContract:
    determinant_fields: Sequence[str]
    dependent_field: str
    confidence_score: float
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.determinant_fields, Sequence):
            raise DetectionFunctionalDependencyContractError("DETERMINANT_FIELDS_MUST_BE_SEQUENCE")
        if not self.determinant_fields:
            raise DetectionFunctionalDependencyContractError("DETERMINANT_FIELDS_EMPTY")
        
        for field in self.determinant_fields:
            if not isinstance(field, str) or not field.strip():
                raise DetectionFunctionalDependencyContractError("DETERMINANT_FIELDS_MUST_CONTAIN_STRINGS")

        if not isinstance(self.dependent_field, str):
            raise DetectionFunctionalDependencyContractError("DEPENDENT_FIELD_MUST_BE_STRING")
        if not self.dependent_field.strip():
            raise DetectionFunctionalDependencyContractError("DEPENDENT_FIELD_EMPTY")

        if self.dependent_field in self.determinant_fields:
            raise DetectionFunctionalDependencyContractError("DEPENDENT_FIELD_CANNOT_BE_IN_DETERMINANT_FIELDS")

        if not isinstance(self.confidence_score, float):
            raise DetectionFunctionalDependencyContractError("CONFIDENCE_SCORE_MUST_BE_FLOAT")
        if not (0.0 <= self.confidence_score <= 1.0):
            raise DetectionFunctionalDependencyContractError("CONFIDENCE_SCORE_MUST_BE_BETWEEN_0_AND_1")

        if not isinstance(self.version, str):
            raise DetectionFunctionalDependencyContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise DetectionFunctionalDependencyContractError("VERSION_EMPTY")

#~~~~~~[FILE END: detection_functional_dependency_contract.py ]~~~~~~#

