@dataclass(frozen=True, slots=True)
class DetectionInclusionDependencyContract:
    subset_field: str
    superset_field: str
    inclusion_ratio: float
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.subset_field, str):
            raise DetectionInclusionDependencyContractError("SUBSET_FIELD_MUST_BE_STRING")
        if not self.subset_field.strip():
            raise DetectionInclusionDependencyContractError("SUBSET_FIELD_EMPTY")

        if not isinstance(self.superset_field, str):
            raise DetectionInclusionDependencyContractError("SUPERSET_FIELD_MUST_BE_STRING")
        if not self.superset_field.strip():
            raise DetectionInclusionDependencyContractError("SUPERSET_FIELD_EMPTY")

        if self.subset_field == self.superset_field:
            raise DetectionInclusionDependencyContractError("SUBSET_CANNOT_EQUAL_SUPERSET")

        if not isinstance(self.inclusion_ratio, float):
            raise DetectionInclusionDependencyContractError("INCLUSION_RATIO_MUST_BE_FLOAT")
        if not (0.0 <= self.inclusion_ratio <= 1.0):
            raise DetectionInclusionDependencyContractError("INCLUSION_RATIO_MUST_BE_BETWEEN_0_AND_1")

        if not isinstance(self.version, str):
            raise DetectionInclusionDependencyContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise DetectionInclusionDependencyContractError("VERSION_EMPTY")

