@dataclass(frozen=True, slots=True)
class DetectionSensitiveGeoContract:
    field_name: str
    precision_decimals: int
    is_residential_resolution: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.field_name, str):
            raise DetectionSensitiveGeoContractError("FIELD_NAME_MUST_BE_STRING")
        if not self.field_name.strip():
            raise DetectionSensitiveGeoContractError("FIELD_NAME_EMPTY")

        if not isinstance(self.precision_decimals, int):
            raise DetectionSensitiveGeoContractError("PRECISION_DECIMALS_MUST_BE_INT")
