        if self.precision_decimals >= 4 and not self.is_residential_resolution:
            raise DetectionSensitiveGeoContractError("HIGH_PRECISION_IMPLIES_RESIDENTIAL_RESOLUTION")

        if not isinstance(self.version, str):
            raise DetectionSensitiveGeoContractError("VERSION_MUST_BE_STRING")
