class IngestionBackpressureContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class IngestionBackpressureContract:
    is_throttled: bool
    retry_after_seconds: int | None
    throttle_reason: str | None
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.is_throttled, bool):
            raise IngestionBackpressureContractError("IS_THROTTLED_MUST_BE_BOOL")

        if self.retry_after_seconds is not None:
            if not isinstance(self.retry_after_seconds, int):
                raise IngestionBackpressureContractError("RETRY_AFTER_SECONDS_MUST_BE_INT_OR_NONE")
            if self.retry_after_seconds < 0:
                raise IngestionBackpressureContractError("RETRY_AFTER_SECONDS_MUST_BE_NON_NEGATIVE")

        if self.throttle_reason is not None:
            if not isinstance(self.throttle_reason, str):
                raise IngestionBackpressureContractError("THROTTLE_REASON_MUST_BE_STRING_OR_NONE")
            if not self.throttle_reason.strip():
                raise IngestionBackpressureContractError("THROTTLE_REASON_EMPTY")

        if not isinstance(self.version, str):
            raise IngestionBackpressureContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise IngestionBackpressureContractError("VERSION_EMPTY")

