@dataclass(frozen=True, slots=True)
class IngestionContextContract:
    engine_id: str
    connection_timeout_ms: int
    read_timeout_ms: int
    max_retries: int
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.engine_id, str):
            raise IngestionContextContractError("ENGINE_ID_MUST_BE_STRING")
        if not self.engine_id.strip():
            raise IngestionContextContractError("ENGINE_ID_EMPTY")

        for field_name, value in (
            ("connection_timeout_ms", self.connection_timeout_ms),
            ("read_timeout_ms", self.read_timeout_ms),
        ):
            if not isinstance(value, int):
                raise IngestionContextContractError(f"{field_name.upper()}_MUST_BE_INT")
            if value <= 0:
                raise IngestionContextContractError(f"{field_name.upper()}_MUST_BE_POSITIVE")

        if not isinstance(self.max_retries, int):
            raise IngestionContextContractError("MAX_RETRIES_MUST_BE_INT")
        if self.max_retries < 0:
            raise IngestionContextContractError("MAX_RETRIES_MUST_BE_NON_NEGATIVE")

        if not isinstance(self.version, str):
            raise IngestionContextContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise IngestionContextContractError("VERSION_EMPTY")

