#
#   Represents the physical splitting of massive payloads into 
#   smaller chunks during transport (e.g., chunk 2 of 50).
#
# STATUS:
#
#   GK STRICT
#   PURE CONTRACT
#   INGESTION BOUNDARY
#
# ============================================================

from __future__ import annotations

from dataclasses import dataclass
from typing import Final


__all__ = [
    "VERSION",
    "IngestionFragmentationContractError",
    "IngestionFragmentationContract",
]

VERSION: Final[str] = "IngestionFragmentationContract v6.3"


class IngestionFragmentationContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class IngestionFragmentationContract:
    chunk_index: int
    total_chunks: int | None
    is_last_chunk: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.chunk_index, int):
            raise IngestionFragmentationContractError("CHUNK_INDEX_MUST_BE_INT")
        if self.chunk_index < 0:
            raise IngestionFragmentationContractError("CHUNK_INDEX_MUST_BE_NON_NEGATIVE")

        if self.total_chunks is not None:
            if not isinstance(self.total_chunks, int):
                raise IngestionFragmentationContractError("TOTAL_CHUNKS_MUST_BE_INT_OR_NONE")
            if self.total_chunks <= 0:
                raise IngestionFragmentationContractError("TOTAL_CHUNKS_MUST_BE_POSITIVE")
            if self.chunk_index >= self.total_chunks:
                raise IngestionFragmentationContractError("CHUNK_INDEX_MUST_BE_LESS_THAN_TOTAL_CHUNKS")

        if not isinstance(self.is_last_chunk, bool):
            raise IngestionFragmentationContractError("IS_LAST_CHUNK_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise IngestionFragmentationContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise IngestionFragmentationContractError("VERSION_EMPTY")

#~~~~~~[FILE END: ingestion_fragmentation_contract.py ]~~~~~~#

