class IngestionResultContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class IngestionResultContract:
    run_id: str
    
    # Context & Engine
    context: IngestionContextContract
    source_connection: IngestionSourceConnectionContract
    auth_context: IngestionAuthContextContract
    strategy: IngestionStrategyContract
    
    # State & Boundary
    watermark: IngestionWatermarkContract | None
    pagination_cursor: IngestionPaginationCursorContract | None
    window: IngestionWindowContract | None
    
    # Data & Transport
    raw_payload: IngestionRawPayloadContract | None
    payload_signature: IngestionPayloadSignatureContract | None
    fragmentation: IngestionFragmentationContract | None
    
    # Landing & Storage
    landing_reference: IngestionLandingReferenceContract | None
    partition_routing: IngestionPartitionRoutingContract | None
    
    # Source Health
    backpressure: IngestionBackpressureContract | None
    schema_drift: IngestionSourceSchemaDriftContract | None
    
    # Observability
    telemetry: IngestionTelemetryContract
    diagnostics: Sequence[IngestionDiagnosticContract]
    
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.run_id, str):
            raise IngestionResultContractError("RUN_ID_MUST_BE_STRING")
        if not self.run_id.strip():
            raise IngestionResultContractError("RUN_ID_EMPTY")

        if not isinstance(self.context, IngestionContextContract):
            raise IngestionResultContractError("CONTEXT_MUST_BE_CONTRACT")

        if not isinstance(self.source_connection, IngestionSourceConnectionContract):
            raise IngestionResultContractError("SOURCE_CONNECTION_MUST_BE_CONTRACT")

        if not isinstance(self.auth_context, IngestionAuthContextContract):
            raise IngestionResultContractError("AUTH_CONTEXT_MUST_BE_CONTRACT")

        if not isinstance(self.strategy, IngestionStrategyContract):
            raise IngestionResultContractError("STRATEGY_MUST_BE_CONTRACT")

        if not isinstance(self.telemetry, IngestionTelemetryContract):
            raise IngestionResultContractError("TELEMETRY_MUST_BE_CONTRACT")

        if not isinstance(self.diagnostics, Sequence):
            raise IngestionResultContractError("DIAGNOSTICS_MUST_BE_SEQUENCE")
        for diag in self.diagnostics:
            if not isinstance(diag, IngestionDiagnosticContract):
                raise IngestionResultContractError("DIAGNOSTICS_MUST_CONTAIN_CONTRACTS")

        if not isinstance(self.version, str):
            raise IngestionResultContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise IngestionResultContractError("VERSION_EMPTY")

