#
#   Immutable ingestion fault tolerance atom.
#
# PURPOSE:
#
#   Tracks the exact retry attempt for an API call or database query,
#   controlling exponential backoff and jitter strategies on failures.
#
# STATUS:
#
#   GK STRICT
#   PURE CONTRACT
#   INGESTION BOUNDARY
#
# ============================================================

from __future__ import annotations

from dataclasses import dataclass
from typing import Final


__all__ = [
    "VERSION",
    "IngestionRetryStateContractError",
    "IngestionRetryStateContract",
]

VERSION: Final[str] = "IngestionRetryStateContract v6.3"


class IngestionRetryStateContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class IngestionRetryStateContract:
    current_attempt: int
    max_attempts: int
    next_backoff_seconds: float
    has_exhausted_retries: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.current_attempt, int):
            raise IngestionRetryStateContractError("CURRENT_ATTEMPT_MUST_BE_INT")
        if self.current_attempt < 1:
            raise IngestionRetryStateContractError("CURRENT_ATTEMPT_MUST_BE_AT_LEAST_ONE")

        if not isinstance(self.max_attempts, int):
            raise IngestionRetryStateContractError("MAX_ATTEMPTS_MUST_BE_INT")
        if self.max_attempts < 1:
            raise IngestionRetryStateContractError("MAX_ATTEMPTS_MUST_BE_AT_LEAST_ONE")
            
        if self.current_attempt > self.max_attempts and not self.has_exhausted_retries:
             raise IngestionRetryStateContractError("EXHAUSTED_FLAG_MUST_BE_TRUE_IF_LIMIT_REACHED")

        if not isinstance(self.next_backoff_seconds, float):
            raise IngestionRetryStateContractError("NEXT_BACKOFF_SECONDS_MUST_BE_FLOAT")
        if self.next_backoff_seconds < 0.0:
            raise IngestionRetryStateContractError("NEXT_BACKOFF_SECONDS_MUST_BE_NON_NEGATIVE")

        if not isinstance(self.has_exhausted_retries, bool):
            raise IngestionRetryStateContractError("HAS_EXHAUSTED_RETRIES_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise IngestionRetryStateContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise IngestionRetryStateContractError("VERSION_EMPTY")

#~~~~~~[FILE END: ingestion_retry_state_contract.py ]~~~~~~#

