class IotResultContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class IotResultContract:
    processed_payloads: Sequence[IotTelemetryPayloadContract]
    diagnostics: Sequence[IotDiagnosticContract]
    is_success: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.processed_payloads, Sequence):
            raise IotResultContractError("PROCESSED_PAYLOADS_MUST_BE_SEQUENCE")
        for payload in self.processed_payloads:
            if not isinstance(payload, IotTelemetryPayloadContract):
                raise IotResultContractError("PROCESSED_PAYLOADS_MUST_CONTAIN_CONTRACTS")

        if not isinstance(self.diagnostics, Sequence):
            raise IotResultContractError("DIAGNOSTICS_MUST_BE_SEQUENCE")
        for diag in self.diagnostics:
            if not isinstance(diag, IotDiagnosticContract):
                raise IotResultContractError("DIAGNOSTICS_MUST_CONTAIN_CONTRACTS")

        if not isinstance(self.is_success, bool):
            raise IotResultContractError("IS_SUCCESS_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise IotResultContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise IotResultContractError("VERSION_EMPTY")

