class NormalizationZScoreStandardizationContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class NormalizationZScoreStandardizationContract:
    population_mean: float
    population_stddev: float
    standardized_value: float
    version: str = VERSION

    def __post_init__(self) -> None:
        for field_name, value in (
            ("population_mean", self.population_mean),
            ("population_stddev", self.population_stddev),
            ("standardized_value", self.standardized_value),
        ):
            if not isinstance(value, float):
                raise NormalizationZScoreStandardizationContractError(f"{field_name.upper()}_MUST_BE_FLOAT")

        if self.population_stddev <= 0.0:
            raise NormalizationZScoreStandardizationContractError("POPULATION_STDDEV_MUST_BE_POSITIVE")

        if not isinstance(self.version, str):
            raise NormalizationZScoreStandardizationContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise NormalizationZScoreStandardizationContractError("VERSION_EMPTY")

