@dataclass(frozen=True, slots=True)
class ParsingAstNodeContract:
    node_type: str
    node_value: str | None
    children: Sequence[ParsingAstNodeContract]
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.node_type, str):
            raise ParsingAstNodeContractError("NODE_TYPE_MUST_BE_STRING")
        if not self.node_type.strip():
            raise ParsingAstNodeContractError("NODE_TYPE_EMPTY")

        if self.node_value is not None:
            if not isinstance(self.node_value, str):
                raise ParsingAstNodeContractError("NODE_VALUE_MUST_BE_STRING_OR_NONE")

        if not isinstance(self.children, Sequence):
            raise ParsingAstNodeContractError("CHILDREN_MUST_BE_SEQUENCE")
        for child in self.children:
            if not isinstance(child, ParsingAstNodeContract):
                raise ParsingAstNodeContractError("CHILDREN_MUST_CONTAIN_AST_NODES")

        if not isinstance(self.version, str):
            raise ParsingAstNodeContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise ParsingAstNodeContractError("VERSION_EMPTY")

