from __future__ import annotations

from dataclasses import dataclass
from typing import Final, Sequence


__all__ = [
    "VERSION",
    "ParsingColumnarParquetContractError",
    "ParsingColumnarParquetContract",
]

VERSION: Final[str] = "ParsingColumnarParquetContract v6.3"


class ParsingColumnarParquetContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class ParsingColumnarParquetContract:
    row_groups_read: Sequence[int]
    columns_projected: Sequence[str]
    is_dictionary_decoded: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.row_groups_read, Sequence):
            raise ParsingColumnarParquetContractError("ROW_GROUPS_READ_MUST_BE_SEQUENCE")
        for rg in self.row_groups_read:
            if not isinstance(rg, int) or rg < 0:
                raise ParsingColumnarParquetContractError("ROW_GROUPS_READ_MUST_CONTAIN_NON_NEGATIVE_INTS")

        if not isinstance(self.columns_projected, Sequence):
            raise ParsingColumnarParquetContractError("COLUMNS_PROJECTED_MUST_BE_SEQUENCE")
        for col in self.columns_projected:
            if not isinstance(col, str) or not col.strip():
                raise ParsingColumnarParquetContractError("COLUMNS_PROJECTED_MUST_CONTAIN_STRINGS")

        if not isinstance(self.is_dictionary_decoded, bool):
            raise ParsingColumnarParquetContractError("IS_DICTIONARY_DECODED_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise ParsingColumnarParquetContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise ParsingColumnarParquetContractError("VERSION_EMPTY")

#~~~~~~[FILE END: parsing_columnar_parquet_contract.py ]~~~~~~#

