class ParsingResultContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class ParsingResultContract:
    run_id: str
    context: ParsingContextContract
    parsed_collection: ParsingCollectionContract
    dead_letter_queue: ParsingDeadLetterQueueContract | None
    telemetry: ParsingTelemetryContract
    diagnostics: Sequence[ParsingDiagnosticContract]
    is_success: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.run_id, str):
            raise ParsingResultContractError("RUN_ID_MUST_BE_STRING")
        if not self.run_id.strip():
            raise ParsingResultContractError("RUN_ID_EMPTY")

        if not isinstance(self.context, ParsingContextContract):
            raise ParsingResultContractError("CONTEXT_MUST_BE_CONTRACT")

        if not isinstance(self.parsed_collection, ParsingCollectionContract):
            raise ParsingResultContractError("PARSED_COLLECTION_MUST_BE_CONTRACT")

        if self.dead_letter_queue is not None:
            if not isinstance(self.dead_letter_queue, ParsingDeadLetterQueueContract):
                raise ParsingResultContractError("DEAD_LETTER_QUEUE_MUST_BE_CONTRACT_OR_NONE")

        if not isinstance(self.telemetry, ParsingTelemetryContract):
            raise ParsingResultContractError("TELEMETRY_MUST_BE_CONTRACT")

        if not isinstance(self.diagnostics, Sequence):
            raise ParsingResultContractError("DIAGNOSTICS_MUST_BE_SEQUENCE")
        for diag in self.diagnostics:
            if not isinstance(diag, ParsingDiagnosticContract):
                raise ParsingResultContractError("DIAGNOSTICS_MUST_CONTAIN_CONTRACTS")

        if not isinstance(self.is_success, bool):
            raise ParsingResultContractError("IS_SUCCESS_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise ParsingResultContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise ParsingResultContractError("VERSION_EMPTY")

