@dataclass(frozen=True, slots=True)
class ParsingVideoFrameMetadataContract:
    fps: float
    total_frames: int
    resolution_str: str  # e.g., '1920x1080'
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.fps, float):
            raise ParsingVideoFrameMetadataContractError("FPS_MUST_BE_FLOAT")
        if self.fps <= 0.0:
            raise ParsingVideoFrameMetadataContractError("FPS_MUST_BE_POSITIVE")

        if not isinstance(self.total_frames, int):
            raise ParsingVideoFrameMetadataContractError("TOTAL_FRAMES_MUST_BE_INT")
        if self.total_frames <= 0:
            raise ParsingVideoFrameMetadataContractError("TOTAL_FRAMES_MUST_BE_POSITIVE")

        if not isinstance(self.resolution_str, str):
            raise ParsingVideoFrameMetadataContractError("RESOLUTION_STR_MUST_BE_STRING")
        if 'x' not in self.resolution_str:
            raise ParsingVideoFrameMetadataContractError("RESOLUTION_STR_MUST_CONTAIN_X_SEPARATOR")

        if not isinstance(self.version, str):
            raise ParsingVideoFrameMetadataContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise ParsingVideoFrameMetadataContractError("VERSION_EMPTY")

