class PipelineDagEdgeContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class PipelineDagEdgeContract:
    upstream_task_id: str
    downstream_task_id: str
    is_conditional: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.upstream_task_id, str):
            raise PipelineDagEdgeContractError("UPSTREAM_TASK_ID_MUST_BE_STRING")
        if not self.upstream_task_id.strip():
            raise PipelineDagEdgeContractError("UPSTREAM_TASK_ID_EMPTY")

        if not isinstance(self.downstream_task_id, str):
            raise PipelineDagEdgeContractError("DOWNSTREAM_TASK_ID_MUST_BE_STRING")
        if not self.downstream_task_id.strip():
            raise PipelineDagEdgeContractError("DOWNSTREAM_TASK_ID_EMPTY")

        if self.upstream_task_id == self.downstream_task_id:
            raise PipelineDagEdgeContractError("TASK_CANNOT_DEPEND_ON_ITSELF")

        if not isinstance(self.is_conditional, bool):
            raise PipelineDagEdgeContractError("IS_CONDITIONAL_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise PipelineDagEdgeContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise PipelineDagEdgeContractError("VERSION_EMPTY")

