        if not isinstance(self.dataset_name, str):
            raise QualityExpectationRowCountContractError("DATASET_NAME_MUST_BE_STRING")
        if not self.dataset_name.strip():
            raise QualityExpectationRowCountContractError("DATASET_NAME_EMPTY")

        if not isinstance(self.expected_min_rows, int):
            raise QualityExpectationRowCountContractError("EXPECTED_MIN_ROWS_MUST_BE_INT")
