        if self.expected_min_rows > self.expected_max_rows:
            raise QualityExpectationRowCountContractError("EXPECTED_MIN_ROWS_MUST_BE_LESS_THAN_EQUAL_MAX_ROWS")

        if not isinstance(self.version, str):
            raise QualityExpectationRowCountContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise QualityExpectationRowCountContractError("VERSION_EMPTY")

