#   CORE / CONTRACTS / REGISTRY
#
# ROLE:
#
#   Immutable registry schema atom.
#
# PURPOSE:
#
#   A soft-delete marker (tombstone) indicating that a specific schema version,
#   or an entire subject, is officially deprecated and should not be used.
#
# STATUS:
#
#   GK STRICT
#   PURE CONTRACT
#   REGISTRY BOUNDARY
#
# ============================================================

from __future__ import annotations

from dataclasses import dataclass
from typing import Final, Optional


__all__ = [
    "VERSION",
    "RegistrySchemaTombstoneContractError",
    "RegistrySchemaTombstoneContract",
]

VERSION: Final[str] = "RegistrySchemaTombstoneContract v6.3"


class RegistrySchemaTombstoneContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class RegistrySchemaTombstoneContract:
    subject_name: str
    schema_version_id: Optional[int]  # If None, the entire subject is tombstoned
    tombstoned_by: str
    reason_for_deprecation: str
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.subject_name, str):
            raise RegistrySchemaTombstoneContractError("SUBJECT_NAME_MUST_BE_STRING")
        if not self.subject_name.strip():
            raise RegistrySchemaTombstoneContractError("SUBJECT_NAME_EMPTY")

        if self.schema_version_id is not None:
             if not isinstance(self.schema_version_id, int):
                  raise RegistrySchemaTombstoneContractError("SCHEMA_VERSION_ID_MUST_BE_INT_OR_NONE")
             if self.schema_version_id <= 0:
                  raise RegistrySchemaTombstoneContractError("SCHEMA_VERSION_ID_MUST_BE_POSITIVE")

        if not isinstance(self.tombstoned_by, str):
            raise RegistrySchemaTombstoneContractError("TOMBSTONED_BY_MUST_BE_STRING")
        if not self.tombstoned_by.strip():
            raise RegistrySchemaTombstoneContractError("TOMBSTONED_BY_EMPTY")

        if not isinstance(self.reason_for_deprecation, str):
            raise RegistrySchemaTombstoneContractError("REASON_FOR_DEPRECATION_MUST_BE_STRING")
        if not self.reason_for_deprecation.strip():
            raise RegistrySchemaTombstoneContractError("REASON_FOR_DEPRECATION_EMPTY")

        if not isinstance(self.version, str):
            raise RegistrySchemaTombstoneContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise RegistrySchemaTombstoneContractError("VERSION_EMPTY")

#~~~~~~[FILE END: registry_schema_tombstone_contract.py ]~~~~~~#

