class RegistrySchemaVersionContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class RegistrySchemaVersionContract:
    subject_name: str
    schema_version_id: int
    schema_definition_raw: str  # Avro or JSON schema string
    fingerprint_hash: str
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.subject_name, str):
            raise RegistrySchemaVersionContractError("SUBJECT_NAME_MUST_BE_STRING")
        if not self.subject_name.strip():
            raise RegistrySchemaVersionContractError("SUBJECT_NAME_EMPTY")

        if not isinstance(self.schema_version_id, int):
            raise RegistrySchemaVersionContractError("SCHEMA_VERSION_ID_MUST_BE_INT")
        if self.schema_version_id <= 0:
            raise RegistrySchemaVersionContractError("SCHEMA_VERSION_ID_MUST_BE_POSITIVE")

        if not isinstance(self.schema_definition_raw, str):
            raise RegistrySchemaVersionContractError("SCHEMA_DEFINITION_RAW_MUST_BE_STRING")
        if not self.schema_definition_raw.strip():
            raise RegistrySchemaVersionContractError("SCHEMA_DEFINITION_RAW_EMPTY")

        if not isinstance(self.fingerprint_hash, str):
            raise RegistrySchemaVersionContractError("FINGERPRINT_HASH_MUST_BE_STRING")
        if not self.fingerprint_hash.strip():
             raise RegistrySchemaVersionContractError("FINGERPRINT_HASH_EMPTY")

        if not isinstance(self.version, str):
            raise RegistrySchemaVersionContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise RegistrySchemaVersionContractError("VERSION_EMPTY")

