from __future__ import annotations

from dataclasses import dataclass
from typing import Final, Sequence

from ..shared.shared_timestamp_utc_contract import SharedTimestampUtcContract


__all__ = [
    "VERSION",
    "SchemaEvolutionLineageContractError",
    "SchemaEvolutionLineageContract",
]

VERSION: Final[str] = "SchemaEvolutionLineageContract v6.3"


class SchemaEvolutionLineageContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class SchemaEvolutionLineageContract:
    dataset_name: str
    previous_version_id: str
    new_version_id: str
    evolution_timestamp: SharedTimestampUtcContract
    applied_mutations: Sequence[str]  # e.g., ['ADD_COLUMN age', 'DROP_COLUMN birth']
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.dataset_name, str):
            raise SchemaEvolutionLineageContractError("DATASET_NAME_MUST_BE_STRING")
        if not self.dataset_name.strip():
            raise SchemaEvolutionLineageContractError("DATASET_NAME_EMPTY")

        if not isinstance(self.previous_version_id, str):
            raise SchemaEvolutionLineageContractError("PREVIOUS_VERSION_ID_MUST_BE_STRING")
            
        if not isinstance(self.new_version_id, str):
            raise SchemaEvolutionLineageContractError("NEW_VERSION_ID_MUST_BE_STRING")
        if not self.new_version_id.strip():
             raise SchemaEvolutionLineageContractError("NEW_VERSION_ID_EMPTY")

        if not isinstance(self.evolution_timestamp, SharedTimestampUtcContract):
            raise SchemaEvolutionLineageContractError("EVOLUTION_TIMESTAMP_MUST_BE_SHARED_TIMESTAMP")

        if not isinstance(self.applied_mutations, Sequence):
            raise SchemaEvolutionLineageContractError("APPLIED_MUTATIONS_MUST_BE_SEQUENCE")
        for mut in self.applied_mutations:
            if not isinstance(mut, str):
                raise SchemaEvolutionLineageContractError("APPLIED_MUTATIONS_MUST_CONTAIN_STRINGS")

        if not isinstance(self.version, str):
            raise SchemaEvolutionLineageContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise SchemaEvolutionLineageContractError("VERSION_EMPTY")

#~~~~~~[FILE END: schema_evolution_lineage_contract.py ]~~~~~~#

