@dataclass(frozen=True, slots=True)
class SchemaResultContract:
    run_id: str
    context: SchemaRegistryContextContract
    version_pointer: SchemaVersionPointerContract
    topology: Sequence[SchemaFieldDefinitionContract]
    diagnostics: Sequence[SchemaDiagnosticContract]
    is_success: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.run_id, str):
            raise SchemaResultContractError("RUN_ID_MUST_BE_STRING")
        if not self.run_id.strip():
            raise SchemaResultContractError("RUN_ID_EMPTY")

        if not isinstance(self.context, SchemaRegistryContextContract):
            raise SchemaResultContractError("CONTEXT_MUST_BE_CONTRACT")

        if not isinstance(self.version_pointer, SchemaVersionPointerContract):
            raise SchemaResultContractError("VERSION_POINTER_MUST_BE_CONTRACT")

        if not isinstance(self.topology, Sequence):
            raise SchemaResultContractError("TOPOLOGY_MUST_BE_SEQUENCE")
        for field in self.topology:
            if not isinstance(field, SchemaFieldDefinitionContract):
                raise SchemaResultContractError("TOPOLOGY_MUST_CONTAIN_CONTRACTS")

        if not isinstance(self.diagnostics, Sequence):
            raise SchemaResultContractError("DIAGNOSTICS_MUST_BE_SEQUENCE")
        for diag in self.diagnostics:
            if not isinstance(diag, SchemaDiagnosticContract):
                raise SchemaResultContractError("DIAGNOSTICS_MUST_CONTAIN_CONTRACTS")

        if not isinstance(self.is_success, bool):
            raise SchemaResultContractError("IS_SUCCESS_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise SchemaResultContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise SchemaResultContractError("VERSION_EMPTY")

#~~~~~~[FILE END: schema_result_contract.py ]~~~~~~#

