    delta_budget: float
    noise_distribution: str  # e.g., 'LAPLACIAN', 'GAUSSIAN'
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.dataset_name, str):
            raise SecurityDifferentialPrivacyContractError("DATASET_NAME_MUST_BE_STRING")
