        if not isinstance(self.epsilon_budget, float):
            raise SecurityDifferentialPrivacyContractError("EPSILON_BUDGET_MUST_BE_FLOAT")
        if self.epsilon_budget <= 0.0:
            raise SecurityDifferentialPrivacyContractError("EPSILON_BUDGET_MUST_BE_POSITIVE")

