@dataclass(frozen=True, slots=True)
class SecurityKeyRotationContract:
    key_id: str
    last_rotated_timestamp: str
    rotation_period_days: int
    is_compliant: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.key_id, str):
            raise SecurityKeyRotationContractError("KEY_ID_MUST_BE_STRING")
        if not self.key_id.strip():
            raise SecurityKeyRotationContractError("KEY_ID_EMPTY")

        if not isinstance(self.last_rotated_timestamp, str):
            raise SecurityKeyRotationContractError("LAST_ROTATED_TIMESTAMP_MUST_BE_STRING")
        if not self.last_rotated_timestamp.strip():
            raise SecurityKeyRotationContractError("LAST_ROTATED_TIMESTAMP_EMPTY")

        if not isinstance(self.rotation_period_days, int):
            raise SecurityKeyRotationContractError("ROTATION_PERIOD_DAYS_MUST_BE_INT")
