class SharedExecutionStatusContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class SharedExecutionStatusContract:
    status_code: str  # e.g., 'PENDING', 'RUNNING', 'SUCCESS', 'FAILED'
    is_terminal: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.status_code, str):
            raise SharedExecutionStatusContractError("STATUS_CODE_MUST_BE_STRING")
        if self.status_code not in ("PENDING", "RUNNING", "SUCCESS", "FAILED", "CANCELED"):
            raise SharedExecutionStatusContractError("STATUS_CODE_MUST_BE_VALID_ENUM")

        if not isinstance(self.is_terminal, bool):
            raise SharedExecutionStatusContractError("IS_TERMINAL_MUST_BE_BOOL")
        
        # Enforce consistency: SUCCESS, FAILED, CANCELED must be terminal
        if self.is_terminal and self.status_code in ("PENDING", "RUNNING"):
            raise SharedExecutionStatusContractError("PENDING_AND_RUNNING_ARE_NOT_TERMINAL")
        if not self.is_terminal and self.status_code in ("SUCCESS", "FAILED", "CANCELED"):
            raise SharedExecutionStatusContractError("SUCCESS_FAILED_CANCELED_ARE_TERMINAL")

        if not isinstance(self.version, str):
            raise SharedExecutionStatusContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise SharedExecutionStatusContractError("VERSION_EMPTY")

#~~~~~~[FILE END: shared_execution_status_contract.py ]~~~~~~#

