# ============================================================
# Proper File Protocol (PFP) v6.3 — GK SHARED PAGINATION REQUEST CONTRACT
#
# File:
#   data_preprocessing/core/contracts/shared/
#   shared_pagination_request_contract.py
#
# Layer:
#   CORE / CONTRACTS / SHARED
#
# ROLE:
#
#   Immutable shared integration envelope atom.
#
# PURPOSE:
#
#   Standardizes how clients request slices of a large dataset, supporting
#   both offset-based (page/limit) and cursor-based (next_token) pagination.
#
# STATUS:
#
#   GK STRICT
#   PURE CONTRACT
#   SHARED BOUNDARY
#
# ============================================================

from __future__ import annotations

from dataclasses import dataclass
from typing import Final


__all__ = [
    "VERSION",
    "SharedPaginationRequestContractError",
    "SharedPaginationRequestContract",
]

VERSION: Final[str] = "SharedPaginationRequestContract v6.3"


class SharedPaginationRequestContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class SharedPaginationRequestContract:
    limit: int
    offset: int | None
    cursor_token: str | None
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.limit, int):
            raise SharedPaginationRequestContractError("LIMIT_MUST_BE_INT")
        if self.limit <= 0:
            raise SharedPaginationRequestContractError("LIMIT_MUST_BE_POSITIVE")

        if self.offset is not None:
            if not isinstance(self.offset, int):
                raise SharedPaginationRequestContractError("OFFSET_MUST_BE_INT_OR_NONE")
            if self.offset < 0:
                raise SharedPaginationRequestContractError("OFFSET_MUST_BE_NON_NEGATIVE")

        if self.cursor_token is not None and not isinstance(self.cursor_token, str):
            raise SharedPaginationRequestContractError("CURSOR_TOKEN_MUST_BE_STRING_OR_NONE")

        # Must provide either offset or cursor, but not both in a strict system
        if self.offset is not None and self.cursor_token is not None:
            raise SharedPaginationRequestContractError("CANNOT_USE_OFFSET_AND_CURSOR_SIMULTANEOUSLY")

        if not isinstance(self.version, str):
            raise SharedPaginationRequestContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise SharedPaginationRequestContractError("VERSION_EMPTY")

#~~~~~~[FILE END: shared_pagination_request_contract.py ]~~~~~~#

