class SharedTimeoutPolicyContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class SharedTimeoutPolicyContract:
    operation_name: str
    hard_timeout_ms: int
    soft_timeout_ms: int | None
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.operation_name, str):
            raise SharedTimeoutPolicyContractError("OPERATION_NAME_MUST_BE_STRING")
        if not self.operation_name.strip():
            raise SharedTimeoutPolicyContractError("OPERATION_NAME_EMPTY")

        if not isinstance(self.hard_timeout_ms, int):
            raise SharedTimeoutPolicyContractError("HARD_TIMEOUT_MS_MUST_BE_INT")
        if self.hard_timeout_ms <= 0:
            raise SharedTimeoutPolicyContractError("HARD_TIMEOUT_MS_MUST_BE_POSITIVE")

        if self.soft_timeout_ms is not None:
            if not isinstance(self.soft_timeout_ms, int):
                raise SharedTimeoutPolicyContractError("SOFT_TIMEOUT_MS_MUST_BE_INT_OR_NONE")
            if self.soft_timeout_ms >= self.hard_timeout_ms:
                raise SharedTimeoutPolicyContractError("SOFT_TIMEOUT_MUST_BE_LESS_THAN_HARD_TIMEOUT")

        if not isinstance(self.version, str):
            raise SharedTimeoutPolicyContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise SharedTimeoutPolicyContractError("VERSION_EMPTY")

#~~~~~~[FILE END: shared_timeout_policy_contract.py ]~~~~~~#

