class ActualRegistryStateError(Exception):
    """
    Actual registry contract violation.
    """

    pass


# ============================================================
# SNAPSHOT CONTRACT
# ============================================================


@dataclass(frozen=True)
class RegistryEntrySnapshot:
    """
    Immutable observed registry entry.

    Describes discovered state only.

    No lifecycle management.
    No loading.
    """

    name: str
    category: str
    source: str


    def __post_init__(self) -> None:

        for field_name, value in (
            ("name", self.name),
            ("category", self.category),
            ("source", self.source),
        ):

            if not isinstance(value, str):
                raise ActualRegistryStateError(
                    f"{field_name.upper()}_MUST_BE_STRING"
                )

            if not value.strip():
                raise ActualRegistryStateError(
                    f"{field_name.upper()}_EMPTY"
                )


# ============================================================
# STATE MODEL
# ============================================================


@dataclass(frozen=True)
class ActualRegistryState:
    """
    Immutable observed registry snapshot.

    Represents what exists.

    Does not:
    - discover entries
    - validate correctness
    - calculate drift
    """

    registry_id: str
    entries: Tuple[RegistryEntrySnapshot, ...]


    def __post_init__(self) -> None:

        if not isinstance(self.registry_id, str):
            raise ActualRegistryStateError(
                "REGISTRY_ID_MUST_BE_STRING"
            )

        if not self.registry_id.strip():
            raise ActualRegistryStateError(
                "REGISTRY_ID_EMPTY"
            )


        if not isinstance(self.entries, tuple):
            raise ActualRegistryStateError(
                "ENTRIES_MUST_BE_TUPLE"
            )


        for entry in self.entries:

            if not isinstance(
                entry,
                RegistryEntrySnapshot,
            ):
                raise ActualRegistryStateError(
                    "INVALID_REGISTRY_ENTRY_SNAPSHOT"
                )


    @property
    def entry_count(self) -> int:
        """
        Deterministic number of observed entries.
        """

        return len(self.entries)

