@dataclass(frozen=True, slots=True)
class SystemBackpressureThresholdContract:
    stream_topology_id: str
    bottleneck_operator_name: str
    backpressure_score: float  # 0.0 (healthy) to 1.0 (fully stalled)
    is_upstream_throttled: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.stream_topology_id, str):
            raise SystemBackpressureThresholdContractError("STREAM_TOPOLOGY_ID_MUST_BE_STRING")
