    checkpoint_id: int
    timeout_duration_ms: int
    aborted_due_to_timeout: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.job_id, str):
            raise SystemCheckpointTimeoutContractError("JOB_ID_MUST_BE_STRING")
