class SystemEventLoopLagContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class SystemEventLoopLagContract:
    node_id: str
    measured_lag_ms: int
    acceptable_lag_threshold_ms: int
    is_blocking_alert: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.node_id, str):
            raise SystemEventLoopLagContractError("NODE_ID_MUST_BE_STRING")
        if not self.node_id.strip():
            raise SystemEventLoopLagContractError("NODE_ID_EMPTY")

        if not isinstance(self.measured_lag_ms, int):
            raise SystemEventLoopLagContractError("MEASURED_LAG_MS_MUST_BE_INT")
        if self.measured_lag_ms < 0:
            raise SystemEventLoopLagContractError("MEASURED_LAG_MS_MUST_BE_NON_NEGATIVE")

        if not isinstance(self.acceptable_lag_threshold_ms, int):
            raise SystemEventLoopLagContractError("ACCEPTABLE_LAG_THRESHOLD_MS_MUST_BE_INT")
        if self.acceptable_lag_threshold_ms <= 0:
            raise SystemEventLoopLagContractError("ACCEPTABLE_LAG_THRESHOLD_MS_MUST_BE_POSITIVE")

        if not isinstance(self.is_blocking_alert, bool):
            raise SystemEventLoopLagContractError("IS_BLOCKING_ALERT_MUST_BE_BOOL")
            
        if self.measured_lag_ms > self.acceptable_lag_threshold_ms and not self.is_blocking_alert:
             raise SystemEventLoopLagContractError("ALERT_MUST_BE_TRUE_IF_THRESHOLD_EXCEEDED")

        if not isinstance(self.version, str):
            raise SystemEventLoopLagContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise SystemEventLoopLagContractError("VERSION_EMPTY")

#~~~~~~[FILE END: system_event_loop_lag_contract.py ]~~~~~~#

