class SystemGpuMemoryFragmentationContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class SystemGpuMemoryFragmentationContract:
    gpu_uuid: str
    total_free_bytes: int
    largest_free_block_bytes: int
    requested_allocation_bytes: int
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.gpu_uuid, str):
            raise SystemGpuMemoryFragmentationContractError("GPU_UUID_MUST_BE_STRING")
        if not self.gpu_uuid.strip():
            raise SystemGpuMemoryFragmentationContractError("GPU_UUID_EMPTY")

        if not isinstance(self.total_free_bytes, int):
            raise SystemGpuMemoryFragmentationContractError("TOTAL_FREE_BYTES_MUST_BE_INT")
        if self.total_free_bytes <= 0:
            raise SystemGpuMemoryFragmentationContractError("TOTAL_FREE_BYTES_MUST_BE_POSITIVE")

        if not isinstance(self.largest_free_block_bytes, int):
            raise SystemGpuMemoryFragmentationContractError("LARGEST_FREE_BLOCK_BYTES_MUST_BE_INT")
        if self.largest_free_block_bytes <= 0:
             raise SystemGpuMemoryFragmentationContractError("LARGEST_FREE_BLOCK_BYTES_MUST_BE_POSITIVE")
             
        if self.largest_free_block_bytes > self.total_free_bytes:
             raise SystemGpuMemoryFragmentationContractError("BLOCK_SIZE_CANNOT_EXCEED_TOTAL_FREE")

        if not isinstance(self.requested_allocation_bytes, int):
            raise SystemGpuMemoryFragmentationContractError("REQUESTED_ALLOCATION_BYTES_MUST_BE_INT")
            
        if self.requested_allocation_bytes <= self.largest_free_block_bytes:
             raise SystemGpuMemoryFragmentationContractError("REQUEST_MUST_BE_LARGER_THAN_BLOCK_FOR_FRAGMENTATION")
        if self.requested_allocation_bytes > self.total_free_bytes:
             raise SystemGpuMemoryFragmentationContractError("MUST_HAVE_ENOUGH_TOTAL_MEMORY_TO_BE_FRAGMENTATION_ERROR")

        if not isinstance(self.version, str):
            raise SystemGpuMemoryFragmentationContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise SystemGpuMemoryFragmentationContractError("VERSION_EMPTY")

#~~~~~~[FILE END: system_gpu_memory_fragmentation_contract.py ]~~~~~~#

