class SystemNcclCommunicationTimeoutContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class SystemNcclCommunicationTimeoutContract:
    training_job_id: str
    participating_gpu_uuids: Sequence[str]
    failing_rank_id: int
    timeout_duration_ms: int
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.training_job_id, str):
            raise SystemNcclCommunicationTimeoutContractError("TRAINING_JOB_ID_MUST_BE_STRING")
        if not self.training_job_id.strip():
            raise SystemNcclCommunicationTimeoutContractError("TRAINING_JOB_ID_EMPTY")

        if not isinstance(self.participating_gpu_uuids, Sequence):
            raise SystemNcclCommunicationTimeoutContractError("PARTICIPATING_GPU_UUIDS_MUST_BE_SEQUENCE")
        if len(self.participating_gpu_uuids) < 2:
            raise SystemNcclCommunicationTimeoutContractError("NCCL_REQUIRES_AT_LEAST_TWO_GPUS")
        for gpu_uuid in self.participating_gpu_uuids:
             if not isinstance(gpu_uuid, str):
                  raise SystemNcclCommunicationTimeoutContractError("GPU_UUIDS_MUST_BE_STRINGS")

        if not isinstance(self.failing_rank_id, int):
            raise SystemNcclCommunicationTimeoutContractError("FAILING_RANK_ID_MUST_BE_INT")
        if self.failing_rank_id < 0:
            raise SystemNcclCommunicationTimeoutContractError("FAILING_RANK_ID_MUST_BE_NON_NEGATIVE")

        if not isinstance(self.timeout_duration_ms, int):
            raise SystemNcclCommunicationTimeoutContractError("TIMEOUT_DURATION_MS_MUST_BE_INT")
        if self.timeout_duration_ms <= 0:
            raise SystemNcclCommunicationTimeoutContractError("TIMEOUT_DURATION_MS_MUST_BE_POSITIVE")

        if not isinstance(self.version, str):
            raise SystemNcclCommunicationTimeoutContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise SystemNcclCommunicationTimeoutContractError("VERSION_EMPTY")

