class SystemQuorumLossContractError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class SystemQuorumLossContract:
    cluster_group: str
    active_nodes_count: int
    required_quorum_count: int
    is_write_availability_lost: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.cluster_group, str):
            raise SystemQuorumLossContractError("CLUSTER_GROUP_MUST_BE_STRING")
        if not self.cluster_group.strip():
            raise SystemQuorumLossContractError("CLUSTER_GROUP_EMPTY")

        if not isinstance(self.active_nodes_count, int):
            raise SystemQuorumLossContractError("ACTIVE_NODES_COUNT_MUST_BE_INT")
        if self.active_nodes_count < 0:
            raise SystemQuorumLossContractError("ACTIVE_NODES_COUNT_MUST_BE_NON_NEGATIVE")

        if not isinstance(self.required_quorum_count, int):
            raise SystemQuorumLossContractError("REQUIRED_QUORUM_COUNT_MUST_BE_INT")
        if self.required_quorum_count <= 0:
            raise SystemQuorumLossContractError("REQUIRED_QUORUM_COUNT_MUST_BE_POSITIVE")
            
        if self.active_nodes_count >= self.required_quorum_count:
             raise SystemQuorumLossContractError("CANNOT_LOSE_QUORUM_IF_ACTIVE_NODES_MEET_REQUIREMENT")

        if not isinstance(self.is_write_availability_lost, bool):
            raise SystemQuorumLossContractError("IS_WRITE_AVAILABILITY_LOST_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise SystemQuorumLossContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise SystemQuorumLossContractError("VERSION_EMPTY")

#~~~~~~[FILE END: system_quorum_loss_contract.py ]~~~~~~#

