    node_id: str
    volume_id: str
    provisioned_iops: int
    attempted_iops: int
    is_throttled: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.node_id, str):
            raise SystemStorageIopsThrottlingContractError("NODE_ID_MUST_BE_STRING")
        if not self.node_id.strip():
            raise SystemStorageIopsThrottlingContractError("NODE_ID_EMPTY")

        if not isinstance(self.volume_id, str):
            raise SystemStorageIopsThrottlingContractError("VOLUME_ID_MUST_BE_STRING")
        if not self.volume_id.strip():
            raise SystemStorageIopsThrottlingContractError("VOLUME_ID_EMPTY")

        if not isinstance(self.provisioned_iops, int):
            raise SystemStorageIopsThrottlingContractError("PROVISIONED_IOPS_MUST_BE_INT")
        if self.provisioned_iops <= 0:
            raise SystemStorageIopsThrottlingContractError("PROVISIONED_IOPS_MUST_BE_POSITIVE")

        if not isinstance(self.attempted_iops, int):
            raise SystemStorageIopsThrottlingContractError("ATTEMPTED_IOPS_MUST_BE_INT")
            
        if self.attempted_iops <= self.provisioned_iops:
             raise SystemStorageIopsThrottlingContractError("THROTTLING_IMPLIES_ATTEMPTED_EXCEEDS_PROVISIONED")

        if not isinstance(self.is_throttled, bool):
            raise SystemStorageIopsThrottlingContractError("IS_THROTTLED_MUST_BE_BOOL")

        if not isinstance(self.version, str):
            raise SystemStorageIopsThrottlingContractError("VERSION_MUST_BE_STRING")
        if not self.version.strip():
            raise SystemStorageIopsThrottlingContractError("VERSION_EMPTY")

